// Generate an AES-256 key from Qrypt quantum entropy and verify it with AES-256-GCM.
// Run with: qrypt-run quickstart.mjs   (Node 20.12+, no dependencies)
import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";
import { writeFileSync } from "node:fs";

process.loadEnvFile(".env");
const token = process.env.QRYPT_API_KEY;
if (!token) throw new Error("QRYPT_API_KEY is not set in .env");

const ERRORS = {
  400: "size out of range (must be 1-512 KiB)",
  401: "Authorization header missing, malformed, or token expired",
  403: "invalid token or monthly quota exhausted",
  429: "rate limited - wait 10+ seconds before retrying",
  500: "Qrypt service error - try again later",
  503: "Qrypt service busy - try again later",
};

const res = await fetch("https://api-eus.qrypt.com/api/v1/quantum-entropy?size=1", {
  headers: {
    Authorization: `Bearer ${token}`,
    Accept: "application/json",
    "User-Agent": "qrypt-aes256-quickstart/1.0",
  },
});
if (!res.ok) {
  throw new Error(`Qrypt API ${res.status}: ${ERRORS[res.status] ?? res.statusText}`);
}

const body = await res.json();
const entropy = Buffer.from(body.random[0], "base64");
if (entropy.length < 32) throw new Error(`expected >= 32 bytes of entropy, got ${entropy.length}`);
const key = entropy.subarray(0, 32);

// Round-trip test with AES-256-GCM
const iv = randomBytes(12);
const message = "Hello from Qrypt quantum entropy!";
const cipher = createCipheriv("aes-256-gcm", key, iv);
const ciphertext = Buffer.concat([cipher.update(message, "utf8"), cipher.final()]);
const tag = cipher.getAuthTag();
const decipher = createDecipheriv("aes-256-gcm", key, iv);
decipher.setAuthTag(tag);
const plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString("utf8");
if (plaintext !== message) throw new Error("AES-256-GCM round trip failed");

// Never print the key itself; show only a fingerprint.
const fingerprint = createHash("sha256").update(key).digest("hex").slice(0, 16);
console.log(`Received ${entropy.length} bytes of quantum entropy`);
console.log(`AES-256 key: ${key.length * 8} bits, SHA-256 fingerprint ${fingerprint}...`);
console.log(`AES-256-GCM round trip OK: "${plaintext}"`);

try {
  writeFileSync("aes256.key", key, { mode: 0o600 });
  console.log("Key saved to aes256.key (raw 32 bytes, mode 0600)");
} catch (err) {
  console.log(`Key not saved to disk (${err.code}); it was used in memory only`);
}

